#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_ctc_loss_v3_grad.h"

#include <cmath>
#include <cstring>
#include <vector>

namespace ascend_kernel {

struct CTCLossV3GradTilingData {
    // Total output size (flattened T * B * C)
    int64_t totalLength;
    int64_t T;
    int64_t B;
    int64_t C;
    int64_t S_max;
    int64_t states;
    int64_t blank;
    int64_t zero_infinity;
    // Per-core batch assignment
    int64_t per_core_b_count;
    int64_t core_b_start;
    // Strides for input tensors
    int64_t log_probs_stride_t;
    int64_t log_probs_stride_b;
    int64_t targets_stride_b;
    int64_t log_alpha_stride_b;
    int64_t log_alpha_stride_t;
};

at::Tensor ctc_loss_v3_grad(
    const at::Tensor &grad,
    const at::Tensor &log_probs,
    const at::Tensor &targets,
    at::IntArrayRef input_lengths,
    at::IntArrayRef target_lengths,
    const at::Tensor &neg_log_likelihood,
    const at::Tensor &log_alpha,
    int64_t blank,
    int64_t zero_infinity)
{
    // ---- Input validation ----
    TORCH_CHECK(log_probs.dim() == 3, "log_probs must be 3D [T, B, C]");
    TORCH_CHECK(log_alpha.dim() == 3, "log_alpha must be 3D [B, T, states]");

    int64_t T = log_probs.size(0);
    int64_t B = log_probs.size(1);
    int64_t C = log_probs.size(2);
    int64_t S_max = targets.size(1);
    int64_t states = log_alpha.size(2);

    auto dtype = log_probs.scalar_type();
    TORCH_CHECK(dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16,
                "log_probs dtype must be float32, float16, or bfloat16");

    // ---- Platform info ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());

    // ---- Create output tensor ----
    auto grad_out = at::empty({T, B, C}, log_probs.options());

    // ---- Tiling calculation ----
    // Split B across cores: each core handles some batch elements
    int64_t usedCores = std::min(coreNum, B);
    if (usedCores < 1) usedCores = 1;
    int64_t per_core_b_count = (B + usedCores - 1) / usedCores;

    // Total flattened output length
    int64_t totalLength = T * B * C;

    // ---- Setup tiling data ----
    int64_t dim = 256;  // blockDim setting

    // ---- Prepare blockDim ----
    // Use usedCores blocks
    int64_t blocks = usedCores * dim;
    int64_t blockDim = dim;

    (void)blocks; // block count managed by kernel launch

    // ---- Strides for input tensor indexing ----
    int64_t log_probs_stride_t = B * C;  // stride for time dimension
    int64_t log_probs_stride_b = C;       // stride for batch dimension

    int64_t targets_stride_b = S_max;     // stride for batch dimension

    int64_t log_alpha_stride_b = T * states;
    int64_t log_alpha_stride_t = states;

    // ---- Launch kernel per core ----
    // We launch one task per core, with each core handling some batch elements
    for (int64_t cid = 0; cid < usedCores; ++cid) {
        int64_t core_b_start = cid * per_core_b_count;
        int64_t core_b_end = std::min(core_b_start + per_core_b_count, B);
        int64_t actual_count = core_b_end - core_b_start;
        if (actual_count <= 0) continue;

        CTCLossV3GradTilingData tilingData;
        tilingData.totalLength = totalLength;
        tilingData.T = T;
        tilingData.B = B;
        tilingData.C = C;
        tilingData.S_max = S_max;
        tilingData.states = states;
        tilingData.blank = blank;
        tilingData.zero_infinity = zero_infinity;
        tilingData.per_core_b_count = actual_count;
        tilingData.core_b_start = core_b_start;
        tilingData.log_probs_stride_t = log_probs_stride_t;
        tilingData.log_probs_stride_b = log_probs_stride_b;
        tilingData.targets_stride_b = targets_stride_b;
        tilingData.log_alpha_stride_b = log_alpha_stride_b;
        tilingData.log_alpha_stride_t = log_alpha_stride_t;

        // All params must be lvalues for EXEC_KERNEL_CMD
        int64_t tilingDataSize = sizeof(CTCLossV3GradTilingData);
        int64_t tilingLen = T;
        int64_t tilingB = B;
        int64_t tilingC = C;
        int64_t tilingS = S_max;
        int64_t tilingStates = states;
        int64_t tilingBlank = blank;
        int64_t tilingZInf = zero_infinity;

        if (dtype == at::kFloat) {
            EXEC_KERNEL_CMD(ctc_loss_v3_grad_float, blockDim,
                            grad, log_probs, targets, neg_log_likelihood,
                            log_alpha, grad_out,
                            tilingData, tilingDataSize,
                            tilingLen, tilingB, tilingC,
                            tilingS, tilingStates, tilingBlank, tilingZInf);
        } else {
            EXEC_KERNEL_CMD(ctc_loss_v3_grad_half, blockDim,
                            grad, log_probs, targets, neg_log_likelihood,
                            log_alpha, grad_out,
                            tilingData, tilingDataSize,
                            tilingLen, tilingB, tilingC,
                            tilingS, tilingStates, tilingBlank, tilingZInf);
        }
    }

    return grad_out;
}

} // namespace ascend_kernel
