18	// ============================================================
19	
20	#include "kernel_operator.h"
21	
22	constexpr int32_t BUFFER_NUM = 2;
23	
24	class Kernel<OpName> {
25	public:
26	    __aicore__ inline Kernel<OpName>() {}
27	
28	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
29	                                int64_t totalRows, int64_t dimLength, int64_t dimLengthAlign,
30	                                int64_t formerNum, int64_t formerLength, int64_t tailLength
31	                                /* , 其他算子特有参数 */)
32	    {
33	        int64_t blockIdx = AscendC::GetBlockIdx();
34	        int64_t rowOffset;
35	
36	        if (blockIdx < formerNum) {
37	            this->blockRows = formerLength;
38	            rowOffset = formerLength * blockIdx;
39	        } else {
40	            this->blockRows = tailLength;
41	            int64_t tailIdx = blockIdx - formerNum;
42	            rowOffset = formerLength * formerNum + tailLength * tailIdx;
43	        }
44	
45	        xGm.SetGlobalBuffer((__gm__ half *)x + rowOffset * dimLengthAlign,
46	                             this->blockRows * dimLengthAlign);
47	        yGm.SetGlobalBuffer((__gm__ half *)y + rowOffset * dimLengthAlign,
48	                             this->blockRows * dimLengthAlign);
49	
50	        this->dimLength = dimLength;
51	        this->dimLengthAlign = dimLengthAlign;
52	
53	        pipe.InitBuffer(inQueueX, BUFFER_NUM, dimLengthAlign * sizeof(half));
54	        pipe.InitBuffer(outQueueY, BUFFER_NUM, dimLengthAlign * sizeof(half));
55	        // FP32 临时缓冲 (升精度计算用)
56	        pipe.InitBuffer(tmpBufA, dimLengthAlign * sizeof(float));
57	        pipe.InitBuffer(tmpBufB, dimLengthAlign * sizeof(float));
58	        // 如需更多临时缓冲:pipe.InitBuffer(tmpBufC, dimLengthAlign * sizeof(float));
59	        
60	    }
61	
62	    __aicore__ inline void Process()
63	    {
64	        for (int64_t row = 0; row < this->blockRows; ++row) {
65	            CopyIn(row);
66	            Compute(row);
67	            CopyOut(row);
68	        }
69	    }
70	
71	private:
72	    __aicore__ inline void CopyIn(int64_t row)
73	    {
74	        AscendC::LocalTensor<half> xLocal = inQueueX.AllocTensor<half>();
75	        AscendC::DataCopy(xLocal, xGm[row * this->dimLengthAlign], this->dimLengthAlign);
76	        inQueueX.EnQue(xLocal);
77	    }
78	
79	    __aicore__ inline void Compute(int64_t row)
80	    {
81	        AscendC::LocalTensor<half> xLocal = inQueueX.DeQue<half>();
82	        AscendC::LocalTensor<half> yLocal = outQueueY.AllocTensor<half>();
83	
84	        AscendC::LocalTensor<float> bufA = tmpBufA.Get<float>();
85	        AscendC::LocalTensor<float> bufB = tmpBufB.Get<float>();
86	
87	        int32_t dimLen = static_cast<int32_t>(this->dimLength);
88	        int32_t dimLenAlign = static_cast<int32_t>(this->dimLengthAlign);
89	
90	        // ==== 在此填充计算逻辑 ====
91	        //
92	        // 升精度:
93	        //   AscendC::Cast(bufA, xLocal, AscendC::RoundMode::CAST_NONE, dimLenAlign);
94	        //
95	        /* 归约示例 (ReduceSum):
96	         *   AscendC::Adds(bufB, bufA, 0.0f, dimLenAlign);  // 备份 (归约可能修改 src)
97	         *   AscendC::ReduceSum<float, true>(tmpResult, bufB, bufA, dimLen);
98	         *   float sumVal = tmpResult.GetValue(0);
99	         */
100	        // 降精度回原类型:
101	        //   AscendC::Cast(yLocal, bufA, AscendC::RoundMode::CAST_RINT, dimLenAlign);
102	
103	        inQueueX.FreeTensor(xLocal);
104	        outQueueY.EnQue<half>(yLocal);
105	    }
106	
107	    __aicore__ inline void CopyOut(int64_t row)
108	    {
109	        AscendC::LocalTensor<half> yLocal = outQueueY.DeQue<half>();
110	        AscendC::DataCopy(yGm[row * this->dimLengthAlign], yLocal, this->dimLengthAlign);
111	        outQueueY.FreeTensor(yLocal);
112	    }
113	
114	private:
115	    AscendC::TPipe pipe;
116	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
