12	// ============================================================
13	// 行处理算子 op_host 模板
14	// 适用: LayerNorm, Softmax, BatchNorm 等按行/维度归约算子
15	// 使用: 复制到 csrc/ops/<op_name>/op_host/<op_name>.cpp，
16	//       替换 <op_name>/<OpName> 占位符，修改参数和 tiling 逻辑
17	// ============================================================
18	
19	#include "torch_kernel_helper.h"
20	#include "tiling/platform/platform_ascendc.h"
21	#include "aclrtlaunch_<op_name>.h"
22	
23	namespace ascend_kernel {
24	
25	at::Tensor <op_name>(const at::Tensor &self /* , 其他输入参数 */)
26	{
27	    // ---- 输入校验 ----
28	    TORCH_CHECK(self.dim() > 0, "<op_name>: input must have at least 1 dimension");
29	    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat,
30	                "<op_name>: only float16 and float32 are supported, got ", self.scalar_type());
31	
32	    // ---- 计算行维度 ----
33	    // 将 tensor 视为 [totalRows, dimLength]
34	    int64_t dimLength = self.size(-1);    // <-- 根据算子语义调整
35	    if (dimLength == 0) {
36	        return at::empty_like(self);
37	    }
38	    int64_t totalRows = self.numel() / dimLength;
39	
40	    if (totalRows == 0) {
41	        return at::empty_like(self);
42	    }
43	
44	    at::Tensor x = self.contiguous();
45	    int64_t dtypeSize = x.element_size();
46	    if (dtypeSize == 0) { dtypeSize = 1; }
47	
48	    // ---- 获取硬件参数 ----
49	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
50	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
51	    uint64_t ubSize;
52	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
53	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
54	
55	    // ---- 对齐 ----
56	    int64_t alignElements = 32 / dtypeSize;
57	    int64_t dimLengthAlign = ((dimLength + alignElements - 1) / alignElements) * alignElements;
58	
59	    // ---- UB 容量检查 ----
60	    // bufferCoefficient = 每元素在 UB 中总占用字节, 从设计文档 UB 分配表推导
61	    // 示例: inQ*4 + outQ*4 + tmpBuf*4 = 12 (fp16 with fp32 compute)
62	    int64_t bufferCoefficient = (dtypeSize == 2) ? 12 : 16; // <-- 根据实际修改
63	    int64_t maxDimLength = ubSizeLimit / bufferCoefficient;
64	    maxDimLength = (maxDimLength / alignElements) * alignElements;
65	    TORCH_CHECK(dimLengthAlign <= maxDimLength,
66	                "<op_name>: dimLength ", dimLength, " exceeds UB capacity (max ", maxDimLength, ")");
67	
68	    // ---- Padding ----
69	    at::Tensor kernelInput;
70	    if (dimLength != dimLengthAlign) {
71	        kernelInput = x.reshape({totalRows, dimLength});
72	        kernelInput = at::constant_pad_nd(kernelInput, {0, dimLengthAlign - dimLength}, 0.0);
73	        kernelInput = kernelInput.contiguous();
74	    } else {
75	        kernelInput = x.reshape({totalRows, dimLengthAlign}).contiguous();
76	    }
77	    at::Tensor kernelOutput = at::empty_like(kernelInput);
78	
79	    // ---- Block 级 tiling (按行分配) ----
80	    int64_t usedCoreNum = std::max(int64_t(1), std::min(totalRows, coreNum));
81	    TORCH_CHECK(usedCoreNum != 0, "usedCoreNum should not be 0");
82	    int64_t formerLength = (totalRows + usedCoreNum - 1) / usedCoreNum;
83	    int64_t tailLength = formerLength - 1;
84	    int64_t formerNum = totalRows - tailLength * usedCoreNum;
85	
86	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
87	
88	    EXEC_KERNEL_CMD(<op_name>, blockDim,
89	                    kernelInput, kernelOutput,
90	                    totalRows, dimLength, dimLengthAlign,
91	                    formerNum, formerLength, tailLength
92	                    /* , 其他算子特有参数 */);
93	
94	    // ---- 去 padding + reshape ----
95	    at::Tensor output = kernelOutput;
96	    if (dimLength != dimLengthAlign) {
97	        output = output.narrow(-1, 0, dimLength).contiguous();
98	    }
99	    output = output.reshape(self.sizes());
100	
101	    return output;
102	}
103	
104	}  // namespace ascend_kernel
