#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_ctc_loss_v3_grad.h"

#include <cmath>

namespace ascend_kernel {

at::Tensor ctc_loss_v3_grad(
    const at::Tensor &grad,
    const at::Tensor &log_probs,
    const at::Tensor &targets,
    at::IntArrayRef input_lengths,
    at::IntArrayRef target_lengths,
    const at::Tensor &neg_log_likelihood,
    const at::Tensor &log_alpha,
    int64_t blank,
    int64_t zero_infinity)
{
    // ---- Input validation ----
    TORCH_CHECK(log_probs.dim() == 3, "log_probs must be 3D [T, B, C]");
    TORCH_CHECK(log_alpha.dim() == 3, "log_alpha must be 3D [B, T, states]");

    int64_t T = log_probs.size(0);
    int64_t B = log_probs.size(1);
    int64_t C = log_probs.size(2);
    int64_t S_max = targets.size(1);
    int64_t states = log_alpha.size(2);

    auto dtype = log_probs.scalar_type();
    TORCH_CHECK(dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16,
                "log_probs dtype must be float32, float16, or bfloat16");

    if (T == 0 || B == 0 || C == 0) {
        return at::empty({T, B, C}, log_probs.options());
    }

    // ---- Contiguous tensors ----
    at::Tensor grad_contig = grad.contiguous();
    at::Tensor log_probs_contig = log_probs.contiguous();
    at::Tensor targets_contig = targets.contiguous();
    at::Tensor nll_contig = neg_log_likelihood.contiguous();
    at::Tensor log_alpha_contig = log_alpha.contiguous();

    // ---- Create output tensor ----
    auto grad_out = at::empty({T, B, C}, log_probs.options());

    // ---- Platform info ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());

    // ---- Block-level tiling: split B across cores ----
    int64_t usedCoreNum = std::min(coreNum, B);
    if (usedCoreNum < 1) usedCoreNum = 1;
    int64_t perCoreBCount = (B + usedCoreNum - 1) / usedCoreNum;

    // ---- Strides for GM indexing ----
    // log_probs: [T, B, C], strides: [B*C, C, 1]
    int64_t lp_stride_t = B * C;
    int64_t lp_stride_b = C;

    // targets: [B, S_max], strides: [S_max, 1]
    int64_t tg_stride_b = S_max;

    // log_alpha: [B, T, states], strides: [T*states, states, 1]
    int64_t la_stride_b = T * states;
    int64_t la_stride_t = states;

    // grad_out: [T, B, C], strides: [B*C, C, 1]
    int64_t go_stride_t = B * C;
    int64_t go_stride_b = C;

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // All lvalues for EXEC_KERNEL_CMD
    int64_t lv_T = T, lv_B = B, lv_C = C;
    int64_t lv_S = S_max, lv_states = states;
    int64_t lv_blank = blank, lv_zinf = zero_infinity;
    int64_t lv_pbc = perCoreBCount;
    int64_t lv_lpst = lp_stride_t, lv_lpsb = lp_stride_b;
    int64_t lv_tgsb = tg_stride_b;
    int64_t lv_last = la_stride_t, lv_lasb = la_stride_b;
    int64_t lv_gost = go_stride_t, lv_gosb = go_stride_b;

    if (dtype == at::kFloat) {
        EXEC_KERNEL_CMD(ctc_loss_v3_grad_float, blockDim,
                        grad_contig, log_probs_contig, targets_contig,
                        nll_contig, log_alpha_contig, grad_out,
                        lv_T, lv_B, lv_C, lv_S, lv_states,
                        lv_blank, lv_zinf, lv_pbc,
                        lv_lpst, lv_lpsb, lv_tgsb,
                        lv_last, lv_lasb, lv_gost, lv_gosb);
    } else {
        EXEC_KERNEL_CMD(ctc_loss_v3_grad_half, blockDim,
                        grad_contig, log_probs_contig, targets_contig,
                        nll_contig, log_alpha_contig, grad_out,
                        lv_T, lv_B, lv_C, lv_S, lv_states,
                        lv_blank, lv_zinf, lv_pbc,
                        lv_lpst, lv_lpsb, lv_tgsb,
                        lv_last, lv_lasb, lv_gost, lv_gosb);
    }

    return grad_out;
}

} // namespace ascend_kernel
