#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;
constexpr float NEG_INF = -1e30f;

// Forward declaration
template <typename T>
class KernelCTCLossV3Grad;

// ================================================================
// Helper: scalar exponential using 1-element UB buffer
// ================================================================
template <typename T>
class ScalarMath {
public:
    __aicore__ inline void Init(AscendC::TPipe *pipe) {
        pipe->InitBuffer(buf_, 1 * sizeof(T));
    }

    __aicore__ inline T Exp(T val) {
        AscendC::LocalTensor<T> b = buf_.Get<T>();
        b.SetValue(0, val);
        AscendC::Exp(b, b, 1);
        return b.GetValue(0);
    }

    __aicore__ inline T Ln(T val) {
        AscendC::LocalTensor<T> b = buf_.Get<T>();
        b.SetValue(0, val);
        AscendC::Ln(b, b, 1);
        return b.GetValue(0);
    }

    __aicore__ inline T Abs(T val) {
        AscendC::LocalTensor<T> b = buf_.Get<T>();
        b.SetValue(0, val);
        AscendC::Abs(b, b, 1);
        return b.GetValue(0);
    }

private:
    AscendC::TBuf<AscendC::TPosition::VECCALC> buf_;
};

// ================================================================
// logsumexp of 3 scalar values
// ================================================================
template <typename T>
__aicore__ inline T LogSumExp3(T v1, T v2, T v3, ScalarMath<T> &sm) {
    // Find max of 3 values (ternary, allowed for scalars)
    T mv = (v1 > v2) ? ((v1 > v3) ? v1 : v3) : ((v2 > v3) ? v2 : v3);

    // Handle all-negative-infinity case
    if (mv <= NEG_INF) {
        return NEG_INF;
    }

    T d1 = v1 - mv;
    T d2 = v2 - mv;
    T d3 = v3 - mv;

    T sum_exp = sm.Exp(d1) + sm.Exp(d2) + sm.Exp(d3);
    T result = mv + sm.Ln(sum_exp);
    return result;
}

template <typename T>
class KernelCTCLossV3Grad {
public:
    __aicore__ inline KernelCTCLossV3Grad() {}

    __aicore__ inline void Init(
        GM_ADDR grad_gm,
        GM_ADDR log_probs_gm,
        GM_ADDR targets_gm,
        GM_ADDR neg_log_likelihood_gm,
        GM_ADDR log_alpha_gm,
        GM_ADDR grad_out_gm,
        int64_t T, int64_t B, int64_t C, int64_t S_max, int64_t states,
        int64_t blank, int64_t zero_infinity,
        int64_t per_core_b_count,
        int64_t lp_stride_t, int64_t lp_stride_b,
        int64_t tg_stride_b,
        int64_t la_stride_t, int64_t la_stride_b,
        int64_t go_stride_t, int64_t go_stride_b)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();
        int64_t core_b_start = blockIdx * per_core_b_count;
        int64_t core_b_end = core_b_start + per_core_b_count;
        if (core_b_end > B) core_b_end = B;
        batchStart_ = core_b_start;
        batchCount_ = core_b_end - core_b_start;

        T_ = T; B_ = B; C_ = C; S_max_ = S_max; states_ = states;
        blank_ = blank; zero_infinity_ = zero_infinity;

        lp_stride_t_ = lp_stride_t; lp_stride_b_ = lp_stride_b;
        tg_stride_b_ = tg_stride_b;
        la_stride_t_ = la_stride_t; la_stride_b_ = la_stride_b;
        go_stride_t_ = go_stride_t; go_stride_b_ = go_stride_b;

        // Set global tensor references (cast GM addresses)
        gradGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(grad_gm));
        logProbsGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(log_probs_gm));
        targetsGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(targets_gm));
        nllGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(neg_log_likelihood_gm));
        logAlphaGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(log_alpha_gm));
        gradOutGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(grad_out_gm));

        // Work buffer sizes (float32 compute)
        int64_t states_align = ((states_ + 7) / 8) * 8;  // 8-element alignment for float
        int64_t C_align = ((C_ + 7) / 8) * 8;            // 8-element alignment for float

        // Init buffers
        scalarMath_.Init(&pipe);

        // Input queue for loading log_probs tiles
        pipe.InitBuffer(inQueue_, BUFFER_NUM, C_align * sizeof(float));
        // Output queue for writing grad_out tiles
        pipe.InitBuffer(outQueue_, BUFFER_NUM, C_align * sizeof(float));

        // Compute buffers (all fp32)
        pipe.InitBuffer(alphaBuf_, states_align * sizeof(float));
        pipe.InitBuffer(betaCurrBuf_, states_align * sizeof(float));
        pipe.InitBuffer(betaNextBuf_, states_align * sizeof(float));
        pipe.InitBuffer(extendedBuf_, states_align * sizeof(int32_t));
        pipe.InitBuffer(classAccBuf_, C_align * sizeof(float));
        pipe.InitBuffer(probBuf_, C_align * sizeof(float));
        pipe.InitBuffer(workBuf_, (C_align > states_align * 3 ? C_align : states_align * 3) * sizeof(float));
    }

    __aicore__ inline void Process() {
        if (batchCount_ <= 0) return;

        for (int64_t localB = 0; localB < batchCount_; ++localB) {
            int64_t b = batchStart_ + localB;
            ComputeForBatch(b);
        }
    }

private:
    // ================================================================
    // Compute gradient for one batch element
    // ================================================================
    __aicore__ inline void ComputeForBatch(int64_t b) {
        // Get target length for this batch from the shape info
        // S_max_ is the padded target dimension, actual length is derived from log_alpha
        int64_t S_n = (states_ - 1) / 2;  // states = 2*S_n + 1
        if (S_n > S_max_) S_n = S_max_;

        // ---- Step 1: Load and build extended targets ----
        AscendC::LocalTensor<int32_t> extended = extendedBuf_.Get<int32_t>();
        BuildExtendedTargets(b, S_n, extended);

        // ---- Step 2: Load NLL and grad scalar ----
        float nll_val = static_cast<float>(nllGm_.GetValue(b));
        float grad_val = static_cast<float>(gradGm_.GetValue(0));
        float z_inv = scalarMath_.Exp(nll_val);  // exp(NLL) = 1/p(l|x)

        // ---- Step 3: Backward DP to compute log_beta ----
        AscendC::LocalTensor<float> beta_curr = betaCurrBuf_.Get<float>();
        AscendC::LocalTensor<float> beta_next = betaNextBuf_.Get<float>();
        AscendC::LocalTensor<float> alpha = alphaBuf_.Get<float>();

        // Initialize beta at time T-1
        InitBeta(T_ - 1, b, S_n, extended, beta_curr);

        // Backward DP: T-2 down to 0
        for (int64_t t = T_ - 2; t >= 0; --t) {
            // Swap: beta_next = beta_curr (from previous iteration)
            AscendC::DataCopy(beta_next, beta_curr, states_);

            // Load log_probs at time t+1
            int64_t t_next = t + 1;  // log_probs at time t+1 needed for DP from t
            LoadLogProbsTile(t_next, b);

            // Compute beta[t] from beta[t+1]
            ComputeBetaStep(t, S_n, extended, beta_next, beta_curr);
        }

        // At this point, beta_curr holds beta[0]

        // ---- Step 4: Compute gradient for each time step ----
        // Re-warm-up beta to time T-1 again (beta_curr holds beta[0] now)
        // We need to re-run the DP forward to get beta for all t
        // Better approach: compute gradient on-the-fly during backward pass?
        // Actually, let's just re-compute beta and gradient together

        // Store beta[t] for all t into a logical sequence.
        // Since states is small, we can recompute as needed.
        // For simplicity: re-run backward DP and compute gradient per step

        // Reset beta for T-1
        InitBeta(T_ - 1, b, S_n, extended, beta_curr);

        // Compute gradient for time T-1 first
        LoadLogProbsTile(T_ - 1, b);
        LoadLogAlphaTile(b, T_ - 1);
        ComputeGradientStep(T_ - 1, b, S_n, extended, beta_curr, alpha,
                           z_inv, grad_val);

        // Backward pass: t = T-2 down to 0
        for (int64_t t = T_ - 2; t >= 0; --t) {
            // Swap buffers
            AscendC::DataCopy(beta_next, beta_curr, states_);

            // Compute beta[t] from beta[t+1]
            int64_t t_next = t + 1;
            LoadLogProbsTile(t_next, b);
            ComputeBetaStep(t, S_n, extended, beta_next, beta_curr);

            // Compute gradient for time t
            LoadLogProbsTile(t, b);
            LoadLogAlphaTile(b, t);
            ComputeGradientStep(t, b, S_n, extended, beta_curr, alpha,
                               z_inv, grad_val);
        }
    }

    // ================================================================
    // Build extended targets: interleave blank with targets
    // extended = [blank, t0, blank, t1, ..., blank, t_{S-1}, blank]
    // length = 2*S+1
    // ================================================================
    __aicore__ inline void BuildExtendedTargets(int64_t b, int64_t S_n,
        AscendC::LocalTensor<int32_t> &extended)
    {
        int64_t num_states = 2 * S_n + 1;

        for (int64_t s = 0; s < num_states; ++s) {
            if (s % 2 == 0) {
                extended.SetValue(s, static_cast<int32_t>(blank_));
            } else {
                int64_t target_pos = (s - 1) / 2;
                int32_t target_val = targetsGm_.GetValue(
                    static_cast<int64_t>(b * tg_stride_b_ + target_pos));
                extended.SetValue(s, target_val);
            }
        }

        // Fill remaining states with 0 (padding, not used)
        for (int64_t s = num_states; s < states_; ++s) {
            extended.SetValue(s, static_cast<int32_t>(0));
        }
    }

    // ================================================================
    // Initialize log_beta at time T-1
    // ================================================================
    __aicore__ inline void InitBeta(int64_t t, int64_t b, int64_t S_n,
        AscendC::LocalTensor<int32_t> &extended,
        AscendC::LocalTensor<float> &beta)
    {
        int64_t num_states = 2 * S_n + 1;

        // Load log_probs at time T-1
        LoadLogProbsTile(t, b);
        AscendC::LocalTensor<float> prob = probBuf_.Get<float>();

        for (int64_t s = 0; s < num_states; ++s) {
            if (s == num_states - 1 || s == num_states - 2) {
                int32_t cls = extended.GetValue(s);
                if (cls >= 0 && cls < C_) {
                    beta.SetValue(s, prob.GetValue(static_cast<int64_t>(cls)));
                } else {
                    beta.SetValue(s, NEG_INF);
                }
            } else {
                beta.SetValue(s, NEG_INF);
            }
        }

        // Fill padding
        for (int64_t s = num_states; s < states_; ++s) {
            beta.SetValue(s, NEG_INF);
        }
    }

    // ================================================================
    // Load one time step of log_probs into probBuf
    // ================================================================
    __aicore__ inline void LoadLogProbsTile(int64_t t, int64_t b) {
        AscendC::LocalTensor<float> prob = probBuf_.Get<float>();

        // Load from GM: log_probs[t, b, :] = log_probs[t * lp_stride_t_ + b * lp_stride_b_]
        int64_t base_offset = t * lp_stride_t_ + b * lp_stride_b_;
        int64_t align_C = ((C_ + 7) / 8) * 8;

        // Element-by-element load for arbitrary C (small in test case)
        // For larger C, use DataCopyPad
        for (int64_t c = 0; c < C_; ++c) {
            T val = logProbsGm_.GetValue(base_offset + c);
            prob.SetValue(c, static_cast<float>(val));
        }
        // Zero padding
        for (int64_t c = C_; c < align_C; ++c) {
            prob.SetValue(c, 0.0f);
        }
    }

    // ================================================================
    // Load one time step of log_alpha into alphaBuf
    // ================================================================
    __aicore__ inline void LoadLogAlphaTile(int64_t b, int64_t t) {
        AscendC::LocalTensor<float> alpha = alphaBuf_.Get<float>();
        int64_t base_offset = b * la_stride_b_ + t * la_stride_t_;

        for (int64_t s = 0; s < states_; ++s) {
            T val = logAlphaGm_.GetValue(base_offset + s);
            alpha.SetValue(s, static_cast<float>(val));
        }
    }

    // ================================================================
    // Compute log_beta[t][s] = logsumexp of 3 transitions
    // from log_beta[t+1] which is in beta_next
    // ================================================================
    __aicore__ inline void ComputeBetaStep(int64_t t, int64_t S_n,
        AscendC::LocalTensor<int32_t> &extended,
        AscendC::LocalTensor<float> &beta_next,
        AscendC::LocalTensor<float> &beta_curr)
    {
        int64_t num_states = 2 * S_n + 1;
        AscendC::LocalTensor<float> prob = probBuf_.Get<float>();
        int64_t t_next = t + 1;  // probBuf already contains log_probs[t+1]

        for (int64_t s = 0; s < num_states; ++s) {
            // Transition 1: stay at same state s
            int32_t cls_s = extended.GetValue(s);
            float v1 = NEG_INF;
            if (cls_s >= 0 && cls_s < C_) {
                v1 = beta_next.GetValue(s) + prob.GetValue(static_cast<int64_t>(cls_s));
            }

            // Transition 2: advance 1 to state s+1
            float v2 = NEG_INF;
            if (s + 1 < num_states) {
                int32_t cls_s1 = extended.GetValue(s + 1);
                if (cls_s1 >= 0 && cls_s1 < C_) {
                    v2 = beta_next.GetValue(s + 1) + prob.GetValue(static_cast<int64_t>(cls_s1));
                }
            }

            // Transition 3: skip blank (advance 2)
            float v3 = NEG_INF;
            if (s + 2 < num_states) {
                int32_t cls_s2 = extended.GetValue(s + 2);
                if (cls_s2 >= 0 && cls_s2 < C_ &&
                    static_cast<int64_t>(cls_s2) != blank_) {
                    v3 = beta_next.GetValue(s + 2) + prob.GetValue(static_cast<int64_t>(cls_s2));
                }
            }

            float result = LogSumExp3<float>(v1, v2, v3, scalarMath_);
            beta_curr.SetValue(s, result);
        }

        // Fill padding
        for (int64_t s = num_states; s < states_; ++s) {
            beta_curr.SetValue(s, NEG_INF);
        }
    }

    // ================================================================
    // Compute gradient for time step t
    // ================================================================
    __aicore__ inline void ComputeGradientStep(int64_t t, int64_t b, int64_t S_n,
        AscendC::LocalTensor<int32_t> &extended,
        AscendC::LocalTensor<float> &beta,
        AscendC::LocalTensor<float> &alpha,
        float z_inv, float grad_val)
    {
        int64_t num_states = 2 * S_n + 1;
        AscendC::LocalTensor<float> prob = probBuf_.Get<float>();
        AscendC::LocalTensor<float> class_acc = classAccBuf_.Get<float>();
        AscendC::LocalTensor<float> work = workBuf_.Get<float>();

        // ---- Initialize class accumulator to -inf ----
        for (int64_t c = 0; c < C_; ++c) {
            class_acc.SetValue(c, NEG_INF);
        }

        // ---- Accumulate per state contribution ----
        for (int64_t s = 0; s < num_states; ++s) {
            float alpha_s = alpha.GetValue(s);
            float beta_s = beta.GetValue(s);
            float contrib = alpha_s + beta_s;

            int32_t cls = extended.GetValue(s);
            if (cls >= 0 && cls < C_) {
                int64_t cl = static_cast<int64_t>(cls);
                float old_acc = class_acc.GetValue(cl);

                // logaddexp: log(exp(a) + exp(b)) = max(a,b) + ln(1 + exp(-|a-b|))
                float new_acc;
                if (old_acc <= NEG_INF) {
                    new_acc = contrib;
                } else {
                    float max_val = (old_acc > contrib) ? old_acc : contrib;
                    float min_val = (old_acc < contrib) ? old_acc : contrib;
                    float diff = min_val - max_val;
                    float one_plus_exp = 1.0f + scalarMath_.Exp(diff);
                    new_acc = max_val + scalarMath_.Ln(one_plus_exp);
                }
                class_acc.SetValue(cl, new_acc);
            }
        }

        // ---- Compute per-class gradient and write to output ----
        int64_t go_base = t * go_stride_t_ + b * go_stride_b_;

        for (int64_t c = 0; c < C_; ++c) {
            float prob_c = prob.GetValue(c);
            float acc_c = class_acc.GetValue(c);

            float sum_exp = (acc_c > NEG_INF + 100.0f) ? scalarMath_.Exp(acc_c) : 0.0f;
            float grad_c = grad_val * (scalarMath_.Exp(prob_c) - z_inv * sum_exp);

            // zero_infinity handling
            if (zero_infinity_ != 0) {
                float abs_g = scalarMath_.Abs(grad_c);
                // Check for inf/nan: abs value is inf or nan
                if (abs_g > 1e30f || abs_g != abs_g) {
                    grad_c = 0.0f;
                }
            }

            gradOutGm_.SetValue(go_base + c, static_cast<T>(grad_c));
        }
    }

private:
    // Tensor references
    AscendC::GlobalTensor<T> gradGm_;
    AscendC::GlobalTensor<T> logProbsGm_;
    AscendC::GlobalTensor<int32_t> targetsGm_;
    AscendC::GlobalTensor<T> nllGm_;
    AscendC::GlobalTensor<T> logAlphaGm_;
    AscendC::GlobalTensor<T> gradOutGm_;

    // Shape parameters
    int64_t T_, B_, C_, S_max_, states_;
    int64_t blank_, zero_infinity_;
    int64_t batchStart_, batchCount_;

    // Strides
    int64_t lp_stride_t_, lp_stride_b_;
    int64_t tg_stride_b_;
    int64_t la_stride_t_, la_stride_b_;
    int64_t go_stride_t_, go_stride_b_;

    // Pipe and buffers
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> alphaBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaCurrBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaNextBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> extendedBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> classAccBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> probBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> workBuf_;
    ScalarMath<float> scalarMath_;
};

