#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;
constexpr float NEG_INF = -1e30f;

// ================================================================
// scalar math helper
// ================================================================
class ScalarMathFp32 {
public:
    __aicore__ inline void Init(AscendC::TPipe *pipe) {
        pipe->InitBuffer(buf_, 1 * sizeof(float));
    }

    __aicore__ inline float Exp(float val) {
        AscendC::LocalTensor<float> b = buf_.Get<float>();
        b.SetValue(0, val);
        AscendC::Exp(b, b, 1);
        return b.GetValue(0);
    }

    __aicore__ inline float Ln(float val) {
        AscendC::LocalTensor<float> b = buf_.Get<float>();
        b.SetValue(0, val);
        AscendC::Ln(b, b, 1);
        return b.GetValue(0);
    }

private:
    AscendC::TBuf<AscendC::TPosition::VECCALC> buf_;
};

__aicore__ inline float LogSumExp3(float v1, float v2, float v3, ScalarMathFp32 &sm) {
    float mv = (v1 > v2) ? ((v1 > v3) ? v1 : v3) : ((v2 > v3) ? v2 : v3);
    if (mv <= NEG_INF) return NEG_INF;
    float d1 = v1 - mv, d2 = v2 - mv, d3 = v3 - mv;
    return mv + sm.Ln(sm.Exp(d1) + sm.Exp(d2) + sm.Exp(d3));
}

__aicore__ inline float LogAddExp2(float a, float b, ScalarMathFp32 &sm) {
    if (a <= NEG_INF) return b;
    if (b <= NEG_INF) return a;
    float mx = (a > b) ? a : b;
    float mn = (a < b) ? a : b;
    return mx + sm.Ln(1.0f + sm.Exp(mn - mx));
}

// ================================================================
// Main kernel class
// ================================================================
template <typename InT>
class KernelCTCLossV3Grad {
public:
    __aicore__ inline KernelCTCLossV3Grad() {}

    __aicore__ inline void Init(
        GM_ADDR grad_gm,
        GM_ADDR log_probs_gm,
        GM_ADDR targets_gm,
        GM_ADDR input_lengths_gm,
        GM_ADDR target_lengths_gm,
        GM_ADDR neg_log_likelihood_gm,
        GM_ADDR log_alpha_gm,
        GM_ADDR grad_out_gm,
        int64_t inT, int64_t inB, int64_t inC,
        int64_t inS_max, int64_t inStates,
        int64_t inBlank, int64_t inZeroInf,
        int64_t inPerCoreBCount,
        int64_t inLpStrideT, int64_t inLpStrideB,
        int64_t inTgStrideB,
        int64_t inLaStrideT, int64_t inLaStrideB,
        int64_t inGoStrideT, int64_t inGoStrideB)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();
        int64_t core_b_start = blockIdx * inPerCoreBCount;
        int64_t core_b_end = core_b_start + inPerCoreBCount;
        if (core_b_end > inB) core_b_end = inB;
        batchStart_ = core_b_start;
        batchCount_ = core_b_end - core_b_start;

        T_ = inT; B_ = inB; C_ = inC; S_max_ = inS_max; states_ = inStates;
        blank_ = inBlank; zero_infinity_ = inZeroInf;

        lpStrideT_ = inLpStrideT; lpStrideB_ = inLpStrideB;
        tgStrideB_ = inTgStrideB;
        laStrideT_ = inLaStrideT; laStrideB_ = inLaStrideB;
        goStrideT_ = inGoStrideT; goStrideB_ = inGoStrideB;

        gradGm_.SetGlobalBuffer((__gm__ InT *)grad_gm);
        logProbsGm_.SetGlobalBuffer((__gm__ InT *)log_probs_gm);
        targetsGm_.SetGlobalBuffer((__gm__ int32_t *)targets_gm);
        inputLengthsGm_.SetGlobalBuffer((__gm__ int32_t *)input_lengths_gm);
        targetLengthsGm_.SetGlobalBuffer((__gm__ int32_t *)target_lengths_gm);
        nllGm_.SetGlobalBuffer((__gm__ InT *)neg_log_likelihood_gm);
        logAlphaGm_.SetGlobalBuffer((__gm__ InT *)log_alpha_gm);
        gradOutGm_.SetGlobalBuffer((__gm__ InT *)grad_out_gm);

        scalarMath_.Init(&pipe);

        int64_t C_align = ((C_ + 7) / 8) * 8;
        int64_t states_align = ((states_ + 7) / 8) * 8;

        pipe.InitBuffer(betaCurrBuf_, states_align * sizeof(float));
        pipe.InitBuffer(betaNextBuf_, states_align * sizeof(float));
        pipe.InitBuffer(extendedBuf_, states_align * sizeof(int32_t));
        pipe.InitBuffer(classAccBuf_, C_align * sizeof(float));
        pipe.InitBuffer(probBuf_, C_align * sizeof(float));
        pipe.InitBuffer(alphaBuf_, states_align * sizeof(float));
    }

    __aicore__ inline void Process() {
        if (batchCount_ <= 0) return;
        for (int64_t localB = 0; localB < batchCount_; ++localB) {
            int64_t b = batchStart_ + localB;
            ComputeForBatch(b);
        }
    }

private:
    __aicore__ inline void ComputeForBatch(int64_t b) {
        // Read per-batch lengths
        int64_t input_len = (int64_t)inputLengthsGm_.GetValue(b);
        int64_t target_len = (int64_t)targetLengthsGm_.GetValue(b);
        if (input_len <= 0 || target_len <= 0) return;

        int64_t S_n = target_len;
        int64_t num_states = 2 * S_n + 1;

        AscendC::LocalTensor<int32_t> extended = extendedBuf_.Get<int32_t>();
        AscendC::LocalTensor<float> beta_curr = betaCurrBuf_.Get<float>();
        AscendC::LocalTensor<float> beta_next = betaNextBuf_.Get<float>();
        AscendC::LocalTensor<float> alpha = alphaBuf_.Get<float>();

        // Skip if state count exceeds allocated buffer
        if (num_states > states_) return;

        // Step 1: Build extended targets
        BuildExtendedTargets(b, S_n, num_states, extended);

        // Step 2: Load scalar params (cast to float)
        float grad_val = (float)gradGm_.GetValue(0);
        float nll_val = (float)nllGm_.GetValue(b);
        float z_inv = scalarMath_.Exp(nll_val);

        // Step 3: Init beta at time input_len - 1 (the last valid time)
        int64_t T_last = input_len - 1;
        InitBeta(S_n, num_states, beta_curr);

        // Step 4: Gradient for time T_last
        LoadLogProbsTile(T_last, b);
        LoadLogAlphaTile(b, T_last, num_states);
        ComputeGradientStep(T_last, b, S_n, num_states, extended, beta_curr, alpha, z_inv, grad_val);

        // Step 5: Backward DP from T_last-1 down to 0
        for (int64_t t = T_last - 1; t >= 0; --t) {
            DescendC::DataCopy(beta_next, beta_curr, num_states);

            // Need log_probs[t+1] for DP transition
            LoadLogProbsTile(t + 1, b);
            ComputeBetaStep(t, S_n, num_states, extended, beta_next, beta_curr);

            // Gradient at time t
            LoadLogProbsTile(t, b);
            LoadLogAlphaTile(b, t, num_states);
            ComputeGradientStep(t, b, S_n, num_states, extended, beta_curr, alpha, z_inv, grad_val);
        }
    }

    __aicore__ inline void BuildExtendedTargets(int64_t b, int64_t S_n, int64_t num_states,
        AscendC::LocalTensor<int32_t> &extended)
    {
        for (int64_t s = 0; s < num_states; ++s) {
            if (s % 2 == 0) {
                extended.SetValue(s, (int32_t)blank_);
            } else {
                int64_t tp = (s - 1) / 2;
                int32_t tv = targetsGm_.GetValue(b * tgStrideB_ + tp);
                extended.SetValue(s, tv);
            }
        }
        for (int64_t s = num_states; s < states_; ++s) {
            extended.SetValue(s, (int32_t)0);
        }
    }

    __aicore__ inline void InitBeta(int64_t S_n, int64_t num_states,
        AscendC::LocalTensor<float> &beta)
    {
        // Beta at final valid time = log(1.0) = 0 for last 2 states, -inf otherwise
        for (int64_t s = 0; s < num_states; ++s) {
            if (s == num_states - 1 || s == num_states - 2) {
                beta.SetValue(s, 0.0f);
            } else {
                beta.SetValue(s, NEG_INF);
            }
        }
        for (int64_t s = num_states; s < states_; ++s) {
            beta.SetValue(s, NEG_INF);
        }
    }

    __aicore__ inline void LoadLogProbsTile(int64_t t, int64_t b) {
        AscendC::LocalTensor<float> prob = probBuf_.Get<float>();
        int64_t base = t * lpStrideT_ + b * lpStrideB_;
        for (int64_t c = 0; c < C_; ++c) {
            prob.SetValue(c, (float)logProbsGm_.GetValue(base + c));
        }
        int64_t C_align = ((C_ + 7) / 8) * 8;
        for (int64_t c = C_; c < C_align; ++c) {
            prob.SetValue(c, 0.0f);
        }
    }

    __aicore__ inline void LoadLogAlphaTile(int64_t b, int64_t t, int64_t num_states) {
        AscendC::LocalTensor<float> alpha = alphaBuf_.Get<float>();
        int64_t base = b * laStrideB_ + t * laStrideT_;
        for (int64_t s = 0; s < num_states; ++s) {
            alpha.SetValue(s, (float)logAlphaGm_.GetValue(base + s));
        }
    }

    __aicore__ inline void ComputeBetaStep(int64_t t, int64_t S_n, int64_t num_states,
        AscendC::LocalTensor<int32_t> &extended,
        AscendC::LocalTensor<float> &beta_next,
        AscendC::LocalTensor<float> &beta_curr)
    {
        AscendC::LocalTensor<float> prob = probBuf_.Get<float>();

        for (int64_t s = 0; s < num_states; ++s) {
            float v1 = NEG_INF, v2 = NEG_INF, v3 = NEG_INF;

            int32_t cs = extended.GetValue(s);
            if (cs >= 0 && cs < (int32_t)C_) {
                v1 = beta_next.GetValue(s) + prob.GetValue((int64_t)cs);
            }

            if (s + 1 < num_states) {
                int32_t cs1 = extended.GetValue(s + 1);
                if (cs1 >= 0 && cs1 < (int32_t)C_) {
                    v2 = beta_next.GetValue(s + 1) + prob.GetValue((int64_t)cs1);
                }
            }

            if (s + 2 < num_states) {
                int32_t cs2 = extended.GetValue(s + 2);
                if (cs2 >= 0 && cs2 < (int32_t)C_ && (int64_t)cs2 != blank_) {
                    v3 = beta_next.GetValue(s + 2) + prob.GetValue((int64_t)cs2);
                }
            }

            beta_curr.SetValue(s, LogSumExp3(v1, v2, v3, scalarMath_));
        }

        for (int64_t s = num_states; s < states_; ++s) {
            beta_curr.SetValue(s, NEG_INF);
        }
    }

    __aicore__ inline void ComputeGradientStep(int64_t t, int64_t b, int64_t S_n,
        int64_t num_states,
        AscendC::LocalTensor<int32_t> &extended,
        AscendC::LocalTensor<float> &beta,
        AscendC::LocalTensor<float> &alpha,
        float z_inv, float grad_val)
    {
        AscendC::LocalTensor<float> prob = probBuf_.Get<float>();
        AscendC::LocalTensor<float> class_acc = classAccBuf_.Get<float>();

        // Init class accumulator
        for (int64_t c = 0; c < C_; ++c) {
            class_acc.SetValue(c, 0.0f);
        }

        // Accumulate α·β per class
        for (int64_t s = 0; s < num_states; ++s) {
            float as = alpha.GetValue(s);
            float bs = beta.GetValue(s);
            float ab = scalarMath_.Exp(as + bs);

            int32_t cls = extended.GetValue(s);
            if (cls >= 0 && cls < (int32_t)C_) {
                int64_t cl = (int64_t)cls;
                class_acc.SetValue(cl, class_acc.GetValue(cl) + ab);
            }
        }

        // grad[t][c] = grad * (exp(lp[t][c]) - Z⁻¹ Σ αβ)
        int64_t go_base = t * goStrideT_ + b * goStrideB_;
        for (int64_t c = 0; c < C_; ++c) {
            float prob_c = prob.GetValue(c);
            float sum_ab = class_acc.GetValue(c);
            float g = grad_val * (scalarMath_.Exp(prob_c) - z_inv * sum_ab);

            if (zero_infinity_ != 0) {
                if (g > 1e30f || g < -1e30f || g != g) g = 0.0f;
            }

            gradOutGm_.SetValue(go_base + c, (InT)g);
        }
    }

private:
    AscendC::GlobalTensor<InT> gradGm_, logProbsGm_, nllGm_, logAlphaGm_, gradOutGm_;
    AscendC::GlobalTensor<int32_t> targetsGm_, inputLengthsGm_, targetLengthsGm_;

    int64_t T_, B_, C_, S_max_, states_, blank_, zero_infinity_;
    int64_t batchStart_, batchCount_;
    int64_t lpStrideT_, lpStrideB_, tgStrideB_;
    int64_t laStrideT_, laStrideB_, goStrideT_, goStrideB_;

    AscendC::TPipe pipe;
    AscendC::TBuf<AscendC::TPosition::VECCALC> alphaBuf_, betaCurrBuf_, betaNextBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> extendedBuf_, classAccBuf_, probBuf_;
    ScalarMathFp32 scalarMath_;
};

